51	void read_block(uint32_t block_id)
52	{
53	    uint64_t sd_block_id = BLOCK_BEGIN_ID + block_id * 8;
54	    sbi_sd_read(kva2pa(BLOCK_CACHE), 8, sd_block_id);
55	    cached_block_id = block_id;
56	}
