52	int main()
53	{
54	    char blank_command[] = "                                                       ";
55	    char prompt[] = "> liangliang678@UCAS_OS: ";
56	
57	    const int SHELL_COMMAND_BEGIN = strlen(prompt) + 1;
58	    const int SHELL_COMMAND_END   = SHELL_WIDTH;
59	 
60	    int input, buf_p;
61	    char buffer[100];
62	
63	    char prev_command[MAX_PREV][100];
64	    for(int i = 0; i < MAX_PREV; i++){
65	        strcpy(prev_command[i], "\0");
66	    }
67	    int back_times = 0;
68	
69	    sys_screen_clear(SHELL_BEGIN, SHELL_END);
70	    sys_move_cursor(1, SHELL_BEGIN);
71	    printf("------------------- COMMAND -------------------");
72	    sys_move_cursor(1, SHELL_END);
73	    printf("------------------- COMMAND -------------------");
74	
75	    print_location_y = SHELL_BEGIN + 1;
76	    sys_move_cursor(1, print_location_y);
77	    while (1)
78	    {   
79	        check_print_location();
80	        printf("%s", prompt);
81	
82	        // call syscall to read UART port
83	        buf_p = 0;
84	        print_location_x = SHELL_COMMAND_BEGIN;
85	        while((input = sys_get_char()) != 13 && input != '\n'){
86	            if(input == '\b' || input == 127){
87	                if(buf_p > 0){
88	                    print_location_x--;
89	                    buf_p--;
90	                    sys_move_cursor(print_location_x, print_location_y);
91	                    printf(" ");
92	                    sys_move_cursor(print_location_x, print_location_y);
93	                }           
94	            }
95	            else if(input == 27){
96	                if(back_times < MAX_PREV){
97	                    strcpy(buffer, prev_command[back_times++]);
98	                    print_location_x = SHELL_COMMAND_BEGIN;
99	                    sys_move_cursor(print_location_x, print_location_y);
100	                    printf("%s", blank_command);
101	                    sys_move_cursor(print_location_x, print_location_y);
102	                    printf("%s", buffer);
103	                    print_location_x += strlen(buffer);
104	                    buf_p = strlen(buffer);
105	                }
106	            }
107	            else{
108	                if(print_location_x < SHELL_COMMAND_END){
109	                    buffer[buf_p++] = (char)input;
110	                    print_location_x++;
111	                    printf("%c",input);
112	                }             
113	            }
114	        }
115	        buffer[buf_p++] = '\0';
116	        for(int i = MAX_PREV - 1; i > 0; i--){
117	            strcpy(prev_command[i], prev_command[i-1]);
118	        }
119	        strcpy(prev_command[0], buffer);
120	        printf("\n");
121	        print_location_y++;
122	        back_times = 0;
123	
124	        // parse input
125	        int argc = 0;
126	        char argv[MAX_ARGC][100];
127	        int argv_p = 0;
128	        int in_argv_flag = 0;
129	 
130	        for(int i = 0; ; i++){
131	            if(buffer[i] == ' ' || buffer[i] == '\0'){
132	                if(in_argv_flag){
133	                    if(argc >= MAX_ARGC){
134	                        check_print_location();
135	                        printf("Too many arguments!\n");
136	                        print_location_y++;
137	                    }
138	                    argv[argc][argv_p++] = '\0';
139	                    argc++;
140	                    argv_p = 0;
141	                }
142	                in_argv_flag = 0;
143	                if(buffer[i] == '\0'){
144	                    break;
145	                }
146	            }
147	            else{
148	                in_argv_flag = 1;
149	                argv[argc][argv_p++] = buffer[i];
150	            }    
151	        }
152	
153	        int empty_command = (argc == 0);
154	        int ps_command = !strcmp(argv[0], "ps");
155	        int reset_command = !strcmp(argv[0], "reset");
156	        int clear_command = !strcmp(argv[0], "clear");
157	        int exec_command = !strcmp(argv[0], "exec");
158	        int kill_command = !strcmp(argv[0], "kill");
159	        int taskset_command = !strcmp(argv[0], "taskset");
160	        int mkfs_command = !strcmp(argv[0], "mkfs");
161	        int statfs_command = !strcmp(argv[0], "statfs");
162	        int mkdir_command = !strcmp(argv[0], "mkdir");
163	        int rmdir_command = !strcmp(argv[0], "rmdir");
164	        int ls_command = !strcmp(argv[0], "ls");
165	        int cd_command = !strcmp(argv[0], "cd");
166	        int touch_command = !strcmp(argv[0], "touch");
167	        int cat_command = !strcmp(argv[0], "cat");
168	        int ln_command = !strcmp(argv[0], "ln");
169	
170	        // exec command and output
171	        if(empty_command){
172	            continue;
173	        }
174	        else if(ps_command){
175	            if(argc >= 2){
176	                check_print_location();
177	                printf("Too many arguments for command ps!\n");
178	                print_location_y++;
179	                continue;
180	            }
181	
182	            char ps_context[(SHELL_END - SHELL_BEGIN - 1) * SHELL_WIDTH + 1];
183	            sys_process_show(ps_context);
184	
185	            char ps_buffer[SHELL_WIDTH + 1];
186	            for(int i = 0; ps_context[i]; i++){
187	                int j = 0;
188	                while(ps_context[i] != '\n' && ps_context[i]){
189	                    ps_buffer[j++] = ps_context[i++];
190	                }
191	                ps_buffer[j++] = '\n';
192	                ps_buffer[j++] = '\0';
193	
194	                check_print_location();
195	                printf("%s", ps_buffer);
196	                print_location_y++;
197	            }
198	        }
199	        else if(reset_command){
200	            if(argc >= 2){
201	                check_print_location();
202	                printf("Too many arguments for command reset!\n");
203	                print_location_y++;
204	                continue;
205	            }
206	
207	            sys_screen_clear(SHELL_BEGIN + 1, SHELL_END - 1);
208	            print_location_y = SHELL_BEGIN + 1;
209	            sys_move_cursor(1, print_location_y);
210	        }
211	        else if(clear_command){
212	            if(argc >= 2){
213	                check_print_location();
214	                printf("Too many arguments for command clear!\n");
215	                print_location_y++;
216	                continue;
217	            }
218	
219	            sys_screen_clear(1, SHELL_BEGIN - 1);
220	            sys_move_cursor(1, print_location_y);
221	        }      
222	        else if(exec_command){
223	            if(argc <= 1){
224	                check_print_location();
225	                printf("Too few arguments for command exec!\n");
226	                print_location_y++;
227	                continue;
228	            }
229	
230	            char* _argv[MAX_ARGC - 1];
231	            for(int i = 0; i < MAX_ARGC - 1; i++){
232	                _argv[i] = argv[i + 1];
233	            } 
234	            int ret = sys_exec(argv[1], argc - 1, _argv, AUTO_CLEANUP_ON_EXIT);
235	            if(ret == 0){
236	                check_print_location();
237	                printf("Too many tasks! Failed to exec %s\n", argv[1]);
238	                print_location_y++;
239	            }
240	            else if(ret == -1){
241	                check_print_location();
242	                printf("Process %s does not exist\n", argv[1]);
243	                print_location_y++;
244	            }
245	            else if(ret == -2){
246	                check_print_location();
247	                printf("Memory full! Failed to exec %s\n", argv[1]);
248	                print_location_y++;
249	            }
250	            else{
251	                check_print_location();
252	                printf("exec process %s\n", argv[1]);
253	                print_location_y++;
254	            }
255	        }
256	        else if(kill_command){
257	            if(argc >= 3){
258	                check_print_location();
259	                printf("Too many arguments for command kill!\n");
260	                print_location_y++;
261	                continue;
262	            }
263	            else if(argc <= 1){
264	                check_print_location();
265	                printf("Too few arguments for command kill!\n");
266	                print_location_y++;
267	                continue;
268	            }
269	            
270	            int pid = atoi(argv[1]);
271	            if(pid == 0 || pid == 1){
272	                check_print_location();
273	                printf("Cannot kill task(pid=%d): Permission Denied!\n", pid);
274	                print_location_y++;
275	            }
276	            else if(!sys_kill(pid)){
277	                check_print_location();
278	                printf("Cannot kill task(pid=%d): Task Does Not Exist!\n", pid);
279	                print_location_y++;
280	            }
281	            else{
282	                check_print_location();
283	                printf("Task(pid=%d) killed\n", pid);
284	                print_location_y++;
285	            }
286	        }
287	        else if(taskset_command){
288	            if(strcmp(argv[1], "-p")){
289	                check_print_location();
290	                printf("usage: taskset -p mask pid\n");
291	                print_location_y++;
292	                continue;
293	            }
294	            if(argc >= 5){
295	                check_print_location();
296	                printf("Too many arguments for command taskset!\n");
297	                print_location_y++;
298	                continue;
299	            }
300	            else if(argc <=3){
301	                check_print_location();
302	                printf("Too few arguments for command taskset!\n");
303	                print_location_y++;
304	                continue;
305	            }
