static int _vprint(const char* fmt, va_list _va,
                   void (*output)(char*))
{
    va_list va;
    va_copy(va, _va);

    int ret;
    char buff[256];

    ret = mini_vsnprintf(buff, 256, fmt, va);

    buff[ret] = '\0';

    output(buff);

    return ret;
}

